const input=$json.body??$json;
const text=v=>v===null||v===undefined?'':String(v).trim();
const bool=v=>typeof v==='boolean'?v:['true','1','yes','on'].includes(text(v).toLowerCase());

const action=text(input.action||'get').toLowerCase();
const clinic_name=text(input.clinic_name);
const service_id=Number(input.service_id??0);
const service_name=text(input.service_name);
const description=text(input.description);
const duration_minutes=Number(input.duration_minutes??20);
const price_amount=Number(input.price_amount??0);
const currency=text(input.currency||'IQD').toUpperCase();
const requires_previsit_guidance=bool(input.requires_previsit_guidance);
const doctor_id=Number(input.doctor_id??0);
const doctor_name=text(input.doctor_name);
const custom_duration_minutes=Number(input.custom_duration_minutes??0);
const custom_price_amount=Number(input.custom_price_amount??0);
const actor_name=text(input.actor_name);
const source_channel=text(input.source_channel||'api').toLowerCase();
const limit=Number(input.limit??100);
const confirm_action=bool(input.confirm_action);

let metadata=input.metadata??{};
try{if(typeof metadata==='string')metadata=JSON.parse(metadata||'{}');}catch{metadata=null;}

const actions=[
 'create','update','activate','deactivate','get','list',
 'assign_doctor','unassign_doctor','list_doctors'
];
const errors=[];

if(!actions.includes(action))errors.push({field:'action',message:'اقدام معتبر نیست.'});
if(!clinic_name)errors.push({field:'clinic_name',message:'نام کلینیک الزامی است.'});
if(!Number.isInteger(service_id)||service_id<0)errors.push({field:'service_id',message:'شناسه خدمت معتبر نیست.'});
if(['create','update','activate','deactivate','get','assign_doctor','unassign_doctor','list_doctors'].includes(action)&&service_id<1&&!service_name){
 errors.push({field:'service_reference',message:'شناسه یا نام خدمت الزامی است.'});
}
if(action==='create'&&!service_name)errors.push({field:'service_name',message:'نام خدمت الزامی است.'});
if(!Number.isInteger(duration_minutes)||duration_minutes<5||duration_minutes>480){
 errors.push({field:'duration_minutes',message:'مدت خدمت باید بین 5 و 480 دقیقه باشد.'});
}
if(!Number.isFinite(price_amount)||price_amount<0)errors.push({field:'price_amount',message:'قیمت معتبر نیست.'});
if(!/^[A-Z]{3}$/.test(currency))errors.push({field:'currency',message:'Currency باید کد سه‌حرفی باشد.'});
if(!Number.isInteger(doctor_id)||doctor_id<0)errors.push({field:'doctor_id',message:'شناسه پزشک معتبر نیست.'});
if(['assign_doctor','unassign_doctor'].includes(action)&&doctor_id<1&&!doctor_name){
 errors.push({field:'doctor_reference',message:'شناسه یا نام پزشک الزامی است.'});
}
if(!Number.isInteger(custom_duration_minutes)||custom_duration_minutes<0||custom_duration_minutes>480){
 errors.push({field:'custom_duration_minutes',message:'مدت اختصاصی معتبر نیست.'});
}
if(!Number.isFinite(custom_price_amount)||custom_price_amount<0)errors.push({field:'custom_price_amount',message:'قیمت اختصاصی معتبر نیست.'});
if(!metadata||Array.isArray(metadata)||typeof metadata!=='object'){
 errors.push({field:'metadata',message:'metadata باید شیء JSON باشد.'});metadata={};
}
if(!['api','manual','import','system'].includes(source_channel))errors.push({field:'source_channel',message:'کانال منبع معتبر نیست.'});
if(!Number.isInteger(limit)||limit<1||limit>500)errors.push({field:'limit',message:'Limit معتبر نیست.'});
if(!['get','list','list_doctors'].includes(action)&&!actor_name)errors.push({field:'actor_name',message:'نام انجام‌دهنده الزامی است.'});
if(!['get','list','list_doctors'].includes(action)&&confirm_action!==true)errors.push({field:'confirm_action',message:'اقدام باید تأیید شود.'});

return [{json:{
 action,clinic_name,service_id,service_name,description,duration_minutes,
 price_amount,currency,requires_previsit_guidance,doctor_id,doctor_name,
 custom_duration_minutes,custom_price_amount,metadata_text:JSON.stringify(metadata),
 actor_name,source_channel,limit,confirm_action,
 validation_status:errors.length?'invalid':'valid',errors
}}];
